import React from 'react';
import { useParams } from 'react-router-dom';
import { fetchPatientProfile } from '../services/api';
import { PatientProfileData } from '../types';

const PatientProfile: React.FC = () => {
    const { patientId } = useParams<{ patientId: string }>();
    const [patientData, setPatientData] = React.useState<PatientProfileData | null>(null);
    const [loading, setLoading] = React.useState<boolean>(true);
    const [error, setError] = React.useState<string | null>(null);

    React.useEffect(() => {
        const getPatientProfile = async () => {
            try {
                const data = await fetchPatientProfile(patientId);
                setPatientData(data);
            } catch (err) {
                setError('Failed to fetch patient profile');
            } finally {
                setLoading(false);
            }
        };

        getPatientProfile();
    }, [patientId]);

    if (loading) {
        return <div>Loading...</div>;
    }

    if (error) {
        return <div>{error}</div>;
    }

    if (!patientData) {
        return <div>No patient data found.</div>;
    }

    return (
        <div>
            <h1>{patientData.name}'s Profile</h1>
            <p>Age: {patientData.age}</p>
            <h2>Mental Health Metrics</h2>
            <ul>
                {patientData.metrics.map((metric, index) => (
                    <li key={index}>{metric}</li>
                ))}
            </ul>
        </div>
    );
};

export default PatientProfile;
